import {readFileSync} from 'node:fs';
import {LanternFirstContentfulPaint} from 'lighthouse/core/computed/metrics/lantern-first-contentful-paint.js';
const [dir, run] = process.argv.slice(2);
const lhr = JSON.parse(readFileSync(`${dir}/run-${run}.json`,'utf8'));
const trace = JSON.parse(readFileSync(`${dir}/run-${run}-0.trace.json`,'utf8'));
const devtoolsLog = JSON.parse(readFileSync(`${dir}/run-${run}-0.devtoolslog.json`,'utf8'));
const context = {computedCache: new Map()};
const data = {trace, devtoolsLog, settings: lhr.configSettings, gatherContext:{gatherMode:'navigation'},
  URL:{requestedUrl: lhr.requestedUrl, mainDocumentUrl: lhr.mainDocumentUrl ?? lhr.finalDisplayedUrl, finalDisplayedUrl: lhr.finalDisplayedUrl}, SourceMaps:[], HostDPR:1, simulator: null};
const r = await LanternFirstContentfulPaint.request(data, context);
const desc = (g, est) => { const nodes=[]; g.traverse(n=>nodes.push(n)); return nodes.map(n=>{const t=est.nodeTimings.get(n); const tt=t?`${Math.round(t.startTime)}-${Math.round(t.endTime)}`:'';
  return n.type==='network'? `NET ${n.request.url.replace(/^https?:\/\/[^/]+/,'')} conn${n.request.connectionId}${n.request.connectionReused?'r':''} ${tt}` : `CPU ${n.id} [${n.childEvents.map(e=>e.name).filter(x=>/Evaluate|Parse|Paint|Layout|Resource|XHR|Function|Timer|Microtask|v8.compile|Compile/.test(x)).slice(0,8).join(',')}] ${tt}`}).join('\n   ');};
console.log(`run ${run}: timing ${Math.round(r.timing)} opt ${Math.round(r.optimisticEstimate.timeInMs)} pess ${Math.round(r.pessimisticEstimate.timeInMs)}`);
console.log(' OPT:\n   '+desc(r.optimisticGraph, r.optimisticEstimate));
console.log(' PESS:\n   '+desc(r.pessimisticGraph, r.pessimisticEstimate));
EOF
for r in 1 3; do node lantern.mjs $S/ci2 $r 2>&1 | head -40; done

