let targetUrls: string[] = argUrls;
let server: ReturnType<typeof createServer> | null = null;

if (targetUrls.length === 0) {
  const port = 4173;
  const distPath = resolve(import.meta.dirname, "../../apps/web/dist");

  const builtHtml = readFileSync(resolve(distPath, "answer.html"), "utf8");

  const enHtml = plantRenderBlocking
    ? builtHtml.replace("</head>", `<link rel="stylesheet" href="${plantedStylesheet}"></head>`)
    : builtHtml;

  const respond = (req: IncomingMessage, res: ServerResponse) => {
    const url = new URL(req.url ?? "/", `http://${req.headers.host}`);

    if (url.pathname === plantedStylesheet) {
      res.writeHead(200, { "content-type": "text/css" });
      res.end("body{}");

      return;
    }

    if (url.pathname === "/exchange" && req.method === "POST") {
      res.writeHead(200, {
        "content-type": "application/json",
        "access-control-allow-origin": "*",
      });
      res.end(
        JSON.stringify({
          roundId: "round-test-1",
          pulseName: "Weekly Pulse",
          minimumGroupSize: 4,
          aiProcessing: false,
          questions: [
            {
              id: "q-1",
              position: 1,
              text: "How was your week?",
              type: { _tag: "Rating", lowLabel: "Low", highLabel: "High", comment: true },
            },
          ],
          actions: [],
          closeTime: 9_999_999,
          state: "open",
          hasAnswered: false,
        }),
      );

      return;
    }

    if (url.pathname.startsWith("/assets/")) {
      const filePath = resolve(distPath, url.pathname.slice(1));

      if (existsSync(filePath)) {
        const contentType = filePath.endsWith(".js")
          ? "application/javascript"
          : filePath.endsWith(".css")
            ? "text/css"
            : "application/octet-stream";

        res.writeHead(200, { "content-type": contentType });
        res.end(readFileSync(filePath));

        return;
      }
    }

    res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    res.end(enHtml);
  };

  server = createServer((req, res) => {
    if (req.headers["sec-fetch-dest"] === "document") {
      respond(req, res);

      return;
    }

    setTimeout(() => respond(req, res), SUBRESOURCE_DELAY_MS);
  });

  await new Promise<void>((res) => {
    server?.listen(port, res);
  });
  targetUrls = [`http://127.0.0.1:${port}/a#t=test-token-123&v=4`];
  console.log(
    `Local test server running at http://127.0.0.1:${port} (subresources delayed ${SUBRESOURCE_DELAY_MS} ms${plantRenderBlocking ? ", planted render-blocking stylesheet" : ""})`,
  );

