    server = createServer((req, res) => {
      const { headers, body } = reply(req);

      res.writeHead(200, headers);

      if (req.headers["sec-fetch-dest"] === "document") {
        res.end(body);

        return;
      }

      res.flushHeaders();
      setTimeout(() => res.end(body), SUBRESOURCE_BODY_DELAY_MS);
    });

